class BinarySearchTest {
    private static int passedTests = 0;

    public static void main(String[] args) {
        runTest("finds an integer in the middle of an array", BinarySearchTest::findsIntegerValue);
        runTest("returns -1 when an integer is missing", BinarySearchTest::returnsMinusOneWhenIntegerValueIsMissing);
        runTest("finds a string value", BinarySearchTest::findsStringValue);
        runTest("finds the first element", BinarySearchTest::findsFirstElement);
        runTest("finds the last element", BinarySearchTest::findsLastElement);
        runTest("returns -1 for an empty array", BinarySearchTest::returnsMinusOneForEmptyArray);
        runTest("finds the only element in a single-element array", BinarySearchTest::findsSingleElement);
        runTest("returns -1 when a single-element array does not contain the target",
                BinarySearchTest::returnsMinusOneForMissingSingleElement);
        runTest("throws an exception for unsorted arrays", BinarySearchTest::throwsExceptionForUnsortedArray);

        System.out.println(passedTests + " BinarySearch tests passed.");
    }

    private static void findsIntegerValue() {
        Integer[] values = {2, 3, 4, 10, 40};

        TestAssertions.assertThat(BinarySearchUtils.binarySearch(values, 10))
                .isEqualTo(3, "Expected to find 10 at its sorted index");
    }

    private static void returnsMinusOneWhenIntegerValueIsMissing() {
        Integer[] values = {2, 3, 4, 10, 40};

        TestAssertions.assertThat(BinarySearchUtils.binarySearch(values, 5))
                .isEqualTo(-1, "Missing values should return -1");
    }

    private static void findsStringValue() {
        String[] values = {"alpha", "bravo", "charlie", "delta"};

        TestAssertions.assertThat(BinarySearchUtils.binarySearch(values, "charlie"))
                .isEqualTo(2, "Expected generic search to support String values");
    }

    private static void findsFirstElement() {
        Integer[] values = {2, 3, 4, 10, 40};

        TestAssertions.assertThat(BinarySearchUtils.binarySearch(values, 2))
                .isEqualTo(0, "Expected to find the first element at index 0");
    }

    private static void findsLastElement() {
        Integer[] values = {2, 3, 4, 10, 40};

        TestAssertions.assertThat(BinarySearchUtils.binarySearch(values, 40))
                .isEqualTo(4, "Expected to find the last element at the final index");
    }

    private static void returnsMinusOneForEmptyArray() {
        Integer[] values = {};

        TestAssertions.assertThat(BinarySearchUtils.binarySearch(values, 10))
                .isEqualTo(-1, "Empty arrays should not contain any target");
    }

    private static void findsSingleElement() {
        Integer[] values = {10};

        TestAssertions.assertThat(BinarySearchUtils.binarySearch(values, 10))
                .isEqualTo(0, "Expected to find the only element at index 0");
    }

    private static void returnsMinusOneForMissingSingleElement() {
        Integer[] values = {10};

        TestAssertions.assertThat(BinarySearchUtils.binarySearch(values, 5))
                .isEqualTo(-1, "Single-element arrays should return -1 when the target is absent");
    }

    private static void throwsExceptionForUnsortedArray() {
        Integer[] values = {2, 10, 4, 40};

        TestAssertions.assertThrows(
                IllegalArgumentException.class,
                () -> BinarySearchUtils.binarySearch(values, 10),
                "Unsorted arrays should be rejected before searching");
    }

    private static void runTest(String name, Runnable test) {
        try {
            test.run();
            passedTests++;
        } catch (AssertionError error) {
            throw new AssertionError("Test failed: " + name + System.lineSeparator() + error.getMessage(), error);
        }
    }
}

import java.util.Objects;

/**
 * Utility methods for searching sorted arrays.
 */
public final class BinarySearchUtils {
    private BinarySearchUtils() {
    }

    /**
     * Searches for {@code target} in {@code array} using binary search.
     *
     * <p>The array must already be sorted in ascending order according to each
     * element's natural ordering, as defined by {@link Comparable#compareTo(Object)}.
     * This method validates that precondition before searching and throws an
     * {@link IllegalArgumentException} when the array is not sorted.</p>
     *
     * <p>The generic type {@code T} must implement {@link Comparable} so that
     * elements can be ordered relative to the target. The {@code ? super T}
     * bound allows a type to be compared by a comparable supertype.</p>
     *
     * <p>The binary search phase runs in {@code O(log n)} time. Because this
     * implementation first validates sorted order with a linear scan, the full
     * method call runs in {@code O(n)} time.</p>
     *
     * @param array the sorted array to search
     * @param target the value to find
     * @param <T> the element type, ordered by its natural {@link Comparable} implementation
     * @return the index of {@code target}, or {@code -1} when the target is absent
     * @throws NullPointerException if {@code array}, {@code target}, or any array element is {@code null}
     * @throws IllegalArgumentException if {@code array} is not sorted in ascending order
     */
    public static <T extends Comparable<? super T>> int binarySearch(T[] array, T target) {
        Objects.requireNonNull(array, "array must not be null");
        Objects.requireNonNull(target, "target must not be null");
        validateSorted(array);

        int low = 0;
        int high = array.length - 1;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            int comparison = array[mid].compareTo(target);

            if (comparison == 0) {
                return mid;
            }

            if (comparison < 0) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        return -1;
    }

    private static <T extends Comparable<? super T>> void validateSorted(T[] array) {
        for (int index = 0; index < array.length; index++) {
            Objects.requireNonNull(array[index], "array elements must not be null");

            if (index > 0 && array[index - 1].compareTo(array[index]) > 0) {
                throw new IllegalArgumentException(
                        "array must be sorted in ascending order; values at indexes "
                                + (index - 1) + " and " + index + " are out of order");
            }
        }
    }
}

final class TestAssertions {
    private TestAssertions() {
    }

    static IntAssertion assertThat(int actual) {
        return new IntAssertion(actual);
    }

    static <T extends Throwable> void assertThrows(
            Class<T> expectedType,
            ThrowingRunnable action,
            String message) {
        try {
            action.run();
        } catch (Throwable actual) {
            if (expectedType.isInstance(actual)) {
                return;
            }

            throw new AssertionError(
                    message + " expected exception:<" + expectedType.getName()
                            + "> but was:<" + actual.getClass().getName() + ">",
                    actual);
        }

        throw new AssertionError(message + " expected exception:<" + expectedType.getName() + "> but nothing was thrown");
    }

    static final class IntAssertion {
        private final int actual;

        private IntAssertion(int actual) {
            this.actual = actual;
        }

        void isEqualTo(int expected, String message) {
            if (actual != expected) {
                throw new AssertionError(message + " expected:<" + expected + "> but was:<" + actual + ">");
            }
        }
    }

    interface ThrowingRunnable {
        void run() throws Throwable;
    }
}

